require("js_asset.js");

var silence_aod_style = {
  name: "silence_aod_style",
  aodPos: 0,
  aodMinute: 0,
  shadowHour:4,
  shadowMinute:4,
  shadowSecond:8,

    onDestory: function (event) {
        FontId = null;
        StringId = null;
        PicId = null;
        return 0;
    },

    onEvent: function (event) {
        switch (event) {
            case WindowEvent.winTop:
            case WindowEvent.winResume:
            case WindowEvent.winReenter:
            case WindowEvent.winAnimationDone:
            case WindowEvent.minTimeout:
            case WindowEvent.secTimeout:
            case WindowEvent.winRepaint:
            case WindowEvent.timeChange:
            this.draw();
            this.drawTimePos();
            break;
        }
        return 0;
    },
    drawTimePos: function()
    {
        if(this.aodMinute != this.wfInfo.min) {
            this.aodMinute = this.wfInfo.min;
            this.aodPos++;
            var posArray = [[0, 0], [0, 2], [0, 4], [0, 6], [2, 6], [4, 6], [6, 6], [6, 4], [6, 2], [6, 0],
                            [6, -2], [6, -4], [6, -6], [4, -6], [2, -6], [0, -6], [-2, -6], [-4, -6], [-6, -6],
                            [-6, -4], [-6, -2], [-6, 0], [-6, 2], [-6, 4], [-6, 6], [-4, 4], [-2, 2]];
            var index = this.aodPos%27;
            var x = posArray[index][0];
            var y = posArray[index][1];
            this.par.x = x;
            this.par.y = y;
        }
    },

    //显示时间
    draw_time: function () {
        var angle = 0;
        //设置时针
        if (WatchfaceUpdata.hour & this.wfInfo.updataFlag) {
            angle = (this.wfInfo.hour * 3600 + this.wfInfo.min * 60) / 12;
            angle = angle << 0; //取整

            this.PicHour.setAngle(angle);
        }
        //设置分针
        if (WatchfaceUpdata.min & this.wfInfo.updataFlag) {
            angle = this.wfInfo.min * 60 + this.wfInfo.sec;
            angle = angle << 0; //取整
            this.PicMinute.setAngle(angle);
        }
    },
    //显示日期
    fixStyle0: function () {
        //显示时分指针
        this.PicHour.x=225;
        this.PicHour.y=92;
        this.PicHour.setPivot(8, 141);

        this.PicMinute.x=225;
        this.PicMinute.y=26;
        this.PicMinute.setPivot(8, 207);
    },
    fixStyle1: function () {
        //显示时分指针
        this.PicHour.x=225;
        this.PicHour.y=80;
        this.PicHour.setPivot(8, 153);

        this.PicMinute.x=223;
        this.PicMinute.y=20;
        this.PicMinute.setPivot(10, 213);
    },
    fixStyle2: function () {
        //显示时分指针
        this.PicHour.x=225;
        this.PicHour.y=80;
        this.PicHour.setPivot(8, 153);
        this.PicMinute.x=223;
        this.PicMinute.y=20;
        this.PicMinute.setPivot(10, 213);
    },
    fixStyle3: function () {
        //显示时分指针
        this.PicHour.x=220;
        this.PicHour.y=79;
        this.PicHour.setPivot(13, 154);
        this.PicMinute.x=219;
        this.PicMinute.y=19;
        this.PicMinute.setPivot(14, 214);
    },
    fixStyle4: function () {
        //显示时分指针
        this.PicHour.x=223;
        this.PicHour.y=79;
        this.PicHour.setPivot(10, 154);
        this.PicMinute.x=223;
        this.PicMinute.y=18;
        this.PicMinute.setPivot(10, 215);
    },
    //替换表盘切图
    drawEditInfo: function () {
        if (this.editInfo.wfStylepoints == 1) {
            this.PicHour.setPic(PicId.Picic_aod_hand_hour_style_2);
            this.PicMinute.setPic(PicId.Picic_aod_hand_minute_style_2);
            this.fixStyle1();
        } else if (this.editInfo.wfStylepoints == 2) {
            this.PicHour.setPic(PicId.Picic_aod_hand_hour_style_3);
            this.PicMinute.setPic(PicId.Picic_aod_hand_minute_style_3);
            this.fixStyle2();
        } else if (this.editInfo.wfStylepoints == 3) {
            this.PicHour.setPic(PicId.Picic_aod_hand_hour_style_4);
            this.PicMinute.setPic(PicId.Picic_aod_hand_minute_style_4);
            this.fixStyle3();
        } else if (this.editInfo.wfStylepoints == 4) {
            this.PicHour.setPic(PicId.Picic_aod_hand_hour_style_5);
            this.PicMinute.setPic(PicId.Picic_aod_hand_minute_style_5);
            this.fixStyle4();
        } else {
            this.PicHour.setPic(PicId.Picic_aod_hand_hour_style_1);
            this.PicMinute.setPic(PicId.Picic_aod_hand_minute_style_1);
            this.fixStyle0();
        }

    },

    draw: function () {
        this.draw_time();
        return 0;
    },

    initEditInfo: function (bytes) {
        var value = new Uint8Array(bytes.data); //将数据转成uint8数组
        if (bytes.data.byteLength >= 16) {
            this.editInfo.wfStyle = value[0];
            this.editInfo.timeStyle = value[1];
            this.editInfo.wfStylepoints = value[2];
            this.editInfo.wfStylebg = value[3];
            this.editInfo.colorNum = (value[12] << 0) + (value[13] << 8) + (value[14] << 16) + (value[15] << 24);
            var colorNum = (bytes.data.byteLength - 16) / 4;
            colorNum = colorNum << 0; //取整
        if (colorNum > this.editInfo.colorNum) {
            colorNum = this.editInfo.colorNum;
        }
        if (colorNum > 20) {
            colorNum = 20;
        }

        this.editInfo.colorNum = colorNum;
        for (var i = 0; i < colorNum; i++) {
                this.editInfo.color[i] =
                (value[16 + i * 4 + 0] << 0) +
                (value[16 + i * 4 + 1] << 8) +
                (value[16 + i * 4 + 2] << 16) +
                (value[16 + i * 4 + 3] << 24);
            }
        }
    },
    readUserData: function () {
        var bytes = new Object();
        var flag = 0;

        FileManager().readFile({
            filePath: "../../files/data.bin",
            success: function (res) {
                print("readFile data.bin success callback " + res.data.byteLength);
                bytes = res;
                flag = 1;
            },
            fail: function (code) {
                print("readFile data.bin fail callback, error code" + code);
            },
            complete: function () {
                print("readFile data.bin complete callback");
            },
        });

        if (flag > 0) {
            //初始化自定义信息
            this.initEditInfo(bytes);
        }
    },

    init: function (par) {
        ImageRelativePath("../");
        //获得表盘参数信息
        this.wfInfo = Watchface();
        this.editInfo = new Object();
        this.editInfo.wfStyle = 0;
        this.editInfo.timeStyle = 0;
        this.editInfo.colorNum = 0;
        this.editInfo.wfStylepoints = 0;
        this.editInfo.wfStylebg = 0;
        this.editInfo.color = new Array(20);
        this.aodMinute = this.wfInfo.min;
        this.readUserData();

        //显示底背景

        //设置editWidget

        //显示刻度
        //显示日期
        //显示时分指针
        this.PicHour = Image(par, PicId.Picic_aod_hand_hour_style_1, 225, 92);
        this.PicHour.setPivot(8, 141);

        this.PicMinute = Image(par, PicId.Picic_aod_hand_minute_style_1, 225, 26);
        this.PicMinute.setPivot(8, 207);

        //设置显示
        this.draw();
        this.drawEditInfo();
        return 0;
    },

    onCreate: function (par, hor_res, ver_res) {
        print("onCreate: ");
        this.hor_max = hor_res;
        this.ver_max = ver_res;
        var fixedPage = View(par, 0, 0, hor_res, ver_res);
        var pageStyle = {
            "main:default": {
            "bg-color": 0x000000,
            "border-side": 0x00,
            "radius": 0,
            "pad-all": 0,
            }
        };
        fixedPage.setLocalStyle(pageStyle);
        this.par = fixedPage;
        this.init(fixedPage);
        return fixedPage;
    }
};

!subwm.registerSubWindow(silence_aod_style);
silence_aod_style = null;
